<script setup lang="ts">
import { computed, ref, watch } from 'vue';
import UButton from '@nuxt/ui/components/Button.vue';
import type { DeliveryPolicyView, DeliveryProjectsView } from '../delivery-project-view';
import { useWorkerSnapshot } from '../useWorkerSnapshot';
import { request, state, date } from '../store';
import DeliveryExecutionPolicy from './DeliveryExecutionPolicy.vue';
import DeliveryPolicyDraftEditor from './DeliveryPolicyDraftEditor.vue';
const projectId = ref(''), selected = ref(''), busy = ref(false), actionError = ref(''), notice = ref(''), acknowledged = ref(false), draftDirty = ref(false);
const projects = useWorkerSnapshot(() => request<DeliveryProjectsView>('/api/requests', 'POST', { action: 'delivery_projects' }));
const { data, error, loading, refreshing, refresh, readAt, now } = useWorkerSnapshot(() => request<DeliveryPolicyView>('/api/requests', 'POST', { action: 'delivery_policy', ...(projectId.value ? { projectId: projectId.value } : {}) }), [projectId]);
const otherApprovals = computed(() => projects.data.value?.approvals?.filter(item => item.repositoryId !== data.value?.repositoryId || item.configurationDigest !== data.value?.configurationDigest) ?? []);
const grantsFresh = computed(() => !!projects.data.value && !state.paused && !projects.error.value && !!projects.readAt.value && now.value - Date.parse(projects.readAt.value) < 15000);
const editorProject = computed(() => projectId.value || data.value?.repositoryId || projects.data.value?.projects.find(item => item.primary)?.repositoryId);
const profile = computed(() => data.value?.configuration.profiles.find(item => item.id === selected.value) ?? data.value?.profile);
const fresh = computed(() => !!data.value && (!projectId.value || data.value.repositoryId === projectId.value) && !state.paused && !error.value && !!readAt.value && now.value - Date.parse(readAt.value) < 15000);
watch([projectId, () => data.value?.configurationDigest, () => state.draftEpoch], () => { acknowledged.value = false; notice.value = ''; actionError.value = ''; });
async function approval(action: 'approve_delivery_policy' | 'revoke_delivery_policy') {
  const current = data.value;
  if (!current?.repositoryId || !fresh.value || busy.value || !acknowledged.value || !state.unlocked) return;
  busy.value = true; actionError.value = ''; const epoch = state.draftEpoch;
  try { await request('/api/requests', 'POST', { action, repositoryId: current.repositoryId, configurationDigest: current.configurationDigest, expectedApprovalRevision: current.approvalRevision }); if (epoch === state.draftEpoch) { acknowledged.value = false; notice.value = action === 'approve_delivery_policy' ? 'This exact committed policy is approved on this worker.' : 'Approval revoked for this policy. Affected work is held; inspect retained evidence before resuming.'; await refresh(); await projects.refresh(); } }
  catch (cause) { if (epoch === state.draftEpoch) actionError.value = (cause as Error).message + ' Refresh committed policy to confirm the saved state before retrying.'; }
  finally { busy.value = false; }
}
async function revokeOlder(repositoryId: string, configurationDigest: string) {
  if (!state.unlocked || busy.value || !grantsFresh.value || !projects.data.value || !otherApprovals.value.some(item => item.repositoryId === repositoryId && item.configurationDigest === configurationDigest)) return;
  busy.value = true; actionError.value = ''; const epoch = state.draftEpoch;
  try { await request('/api/requests', 'POST', { action: 'revoke_delivery_policy', repositoryId, configurationDigest, expectedApprovalRevision: projects.data.value.approvalRevision }); if (epoch === state.draftEpoch) { notice.value = 'The selected older approval was revoked. Affected work is held for inspection.'; await projects.refresh(); await refresh(); } }
  catch (cause) { if (epoch === state.draftEpoch) actionError.value = (cause as Error).message + ' Refresh approvals before retrying.'; }
  finally { busy.value = false; }
}
</script>
<template>
  <section class="delivery-policy" aria-labelledby="delivery-policy-title">
    <header><h2 id="delivery-policy-title">Project delivery policy</h2><UButton variant="outline" color="neutral" :loading="refreshing" :disabled="!state.unlocked || busy" @click="refresh">Refresh committed policy</UButton></header>
    <p>The worker reads <code>.werk/delivery-policy.json</code> from the committed project baseline. Each accepted request keeps its own policy snapshot.</p>
    <label for="delivery-project">Project repository</label><select id="delivery-project" v-model="projectId" :disabled="busy || draftDirty"><option value="">Worker installation project</option><option v-for="project in projects.data.value?.projects ?? []" :key="project.repositoryId" :value="project.repositoryId">{{ project.name }}{{ project.primary ? ' · installation project' : '' }}</option></select><p v-if="draftDirty">Save or discard the current draft before switching projects.</p>
    <p v-if="projects.error.value" role="alert" class="error-text">{{ projects.error.value }}</p><p v-if="error || actionError" role="alert" class="error-text">{{ error || actionError }}</p><p v-if="notice" role="status">{{ notice }}</p><p v-else-if="loading && !data" role="status">Reading the committed project policy…</p>
    <template v-if="data && profile"><dl><div><dt>Default quality profile</dt><dd>{{ data.configuration.defaultProfile }}</dd></div><div><dt>Review notes directory</dt><dd>{{ data.configuration.reviewDirectory }}</dd></div><div><dt>Committed baseline</dt><dd><code>{{ data.baseline }}</code></dd></div><div><dt>Policy version</dt><dd>{{ data.configuration.version }}</dd></div><div><dt>Machine execution limit</dt><dd>{{ data.machineMaxParallel }} slots</dd></div><div><dt>Project execution limit</dt><dd>{{ data.configuration.coordination?.maxActiveRequests ?? 1 }}</dd></div></dl>
      <section class="policy-approval"><h3>{{ data.approved ? 'Approved on this worker' : 'Local approval required' }}</h3><p>Repository configuration proposes authority; this worker grants it only for the exact policy digest. Machine limits and tool permissions still apply. A later policy change requires its own approval.</p><p v-if="!data.approvalRequired">This basic policy does not request expanded authority. Existing machine permissions remain in force.</p><template v-if="data.repositoryId && data.approvalRequired"><label class="check-label"><input v-model="acknowledged" type="checkbox" :disabled="busy" /> I inspected the named providers, remote destination, limits and permitted exceptions below.</label><UButton v-if="!data.approved" :loading="busy" :disabled="!fresh || !acknowledged || busy" @click="approval('approve_delivery_policy')">Approve this exact policy</UButton><UButton v-else color="neutral" variant="outline" :loading="busy" :disabled="!fresh || !acknowledged || busy" @click="approval('revoke_delivery_policy')">Revoke this policy approval</UButton><p v-if="!fresh">Refresh before changing local approval.</p></template></section>
      <label for="delivery-profile-preview">Preview a quality profile</label><select id="delivery-profile-preview" :value="profile.id" @change="selected = ($event.target as HTMLSelectElement).value"><option v-for="item in data.configuration.profiles" :key="item.id" :value="item.id">{{ item.id }}</option></select><dl><div><dt>Minimum acceptance criteria</dt><dd>{{ profile.minimumCriteria }}</dd></div><div><dt>Minimum instruction length</dt><dd>{{ profile.minimumMessageLength }} characters</dd></div><div><dt>Maximum repair attempts</dt><dd>{{ profile.maxRepairAttempts }}</dd></div></dl><p>Previewing a profile here does not change the default or alter accepted work.</p><h3>Protected verification inputs</h3><ul><li v-for="path in profile.verificationInputs" :key="path"><code>{{ path }}</code></li></ul><p v-if="profile.readiness">Semantic readiness assessment required · assumptions {{ profile.readiness.assumptions.replaceAll('_', ' ') }} · estimate limit {{ profile.readiness.maxEstimatedMinutes ?? 'not set' }} minutes.</p><p v-if="profile.exceptions">Exemptible: {{ profile.exceptions.exemptibleCriteria.join(', ') || 'none' }}. Not applicable: {{ profile.exceptions.notApplicableCriteria.join(', ') || 'none' }}.</p>
      <h3>Evidence retention</h3><p v-if="data.retention">Temporary service logs: {{ data.retention.temporaryLogHours === 0 ? 'not retained' : data.retention.temporaryLogHours + ' hours' }}.</p><p>This temporary-log policy does not delete candidate source or review artifacts. Bounded journal and history retention still applies.</p>
      <DeliveryExecutionPolicy v-if="data.configuration.execution" :policy="data.configuration.execution" /><h3>Remote delivery</h3><p v-if="data.configuration.remoteDelivery">{{ data.configuration.remoteDelivery.repository }} · remote {{ data.configuration.remoteDelivery.remote }} · base {{ data.configuration.remoteDelivery.base }} · branch push {{ data.configuration.remoteDelivery.push ? 'permitted' : 'off' }} · PR creation {{ data.configuration.remoteDelivery.pullRequest ? 'permitted' : 'off' }}. Publication remains a separate explicit action.</p><p v-else>Local review notes only. No remote publication authority.</p><details><summary>Complete committed policy and configuration identity</summary><code>{{ data.configurationDigest }}</code><pre style="white-space:pre-wrap;overflow-wrap:anywhere">{{ JSON.stringify(data.configuration, null, 2) }}</pre></details>
    </template>
    <details v-if="otherApprovals.length"><summary>Other approved policy versions · {{ otherApprovals.length }}</summary><p>An older version can still govern pinned work. Revoking it reduces authority on this worker; it does not rewrite evidence or undo completed remote actions. Removed repositories remain listed until their approval is revoked.</p><article v-for="grant in otherApprovals" :key="grant.repositoryId + grant.configurationDigest"><h3>{{ grant.repositoryId }}{{ projects.data.value?.projects.some(item => item.repositoryId === grant.repositoryId) ? '' : ' · repository no longer assigned' }}</h3><p><code>{{ grant.configurationDigest }}</code><br>Approved {{ date(grant.approvedAt) }}</p><UButton variant="outline" color="neutral" :disabled="busy || !grantsFresh" :aria-label="'Revoke older policy for ' + grant.repositoryId + ' ' + grant.configurationDigest" @click="revokeOlder(grant.repositoryId, grant.configurationDigest)">Revoke this older approval</UButton></article><UButton variant="ghost" color="neutral" :disabled="busy" @click="projects.refresh">Refresh approvals</UButton></details>
    <DeliveryPolicyDraftEditor v-if="editorProject" :project-id="editorProject" @dirty="draftDirty = $event" />
  </section>
</template>
<style scoped>
.delivery-policy { min-width: 0; }header { display: flex; align-items: center; justify-content: space-between; gap: var(--space-4); flex-wrap: wrap; }h2 { font-size: 1.25rem; margin: 0; }h3 { font-size: 1rem; margin-top: var(--space-6); }p { max-width: 75ch; font-size: .875rem; line-height: 1.65; }code, dd { overflow-wrap: anywhere; }code { font-size: .8125rem; }dl { display: grid; grid-template-columns: repeat(2,minmax(0,1fr)); gap: var(--space-4); margin-block: var(--space-6); }dt { color: var(--ui-text-muted); font-size: .8125rem; }dd { font-size: .875rem; margin: var(--space-1) 0 0; }.check-label { display: flex; align-items: flex-start; gap: var(--space-3); min-height: 44px; line-height: 1.65; }.check-label input { flex: 0 0 20px; width: 20px; height: 20px; margin-top: .15rem; accent-color: var(--ui-primary); }label { display: block; font-size: .875rem; margin-bottom: var(--space-2); }select { min-height: 44px; border: 1px solid var(--ui-border); background: var(--ui-bg); color: var(--ui-text); padding-inline: var(--space-3); border-radius: 6px; width: min(100%,24rem); }ul { padding-left: var(--space-6); }li { margin-block: var(--space-2); }summary { min-height: 44px; padding-block: var(--space-3); cursor: pointer; font-size: .875rem; }@media (max-width: 560px) { dl { grid-template-columns: 1fr; } }
</style>
